import re
import json
from taf.analyzer.base.log_entry import LogEntry
from decimal import Decimal


class PMLogEntry(LogEntry):
    """
        Provides methods to parse, represent PMLogEntry object in readable format.

    """

    def __init__(self, pm_setup, **kwargs):
        super(PMLogEntry, self).__init__(**kwargs)
        self.__pm_setup = pm_setup

    @property
    def pm_setup(self):
        """
        Provide pm_setup of PMLogEntry

        :return: PMSetup of PMLogEntry
        :rtype: PMSetup
        """

        return self.__pm_setup

    def __str__(self):
        """
        Provide string representation of a PMLogEntry

        :return: String representation of PMLogEntry
        :rtype: str
        """

        result = json.dumps(
            {
                "timestamp": str(self.timestamp),
                "pmsetup": ""
            },
            indent=2)
        result = re.sub(r'""', '"""%s"""' % str(self.__pm_setup), result)
        return result

    def get_pi_value(self, pi_id, dn_re=".*"):
        """
        Get PI value for a given PI ID

        :param str pi_id: PI ID (performance indicator identifier)

        :param str dn_re: distname regex

        :return: Value of PI ID
        :rtype: Union[int, Decimal]
        """
        pi_dict = self.pm_setup.pi_dict(pi_id)[pi_id]
        assert len(pi_dict), (
            "PI ID {pi_id} not found at {time}".format(
                pi_id=pi_id,
                time=self.timestamp))
        dist_names = list(
            filter(
                re.compile(dn_re).search,
                pi_dict.keys()))
        assert len(dist_names) == 1, (
            "matching distnames "
            "for distname regex {dn_re!r} "
            "and PM counter {pi_id} "
            "at {timestamp}: "
            "{dist_names}".format(
                dn_re=dn_re,
                pi_id=pi_id,
                timestamp=self.timestamp,
                dist_names=dist_names))
        pi_value = pi_dict[dist_names[0]]
        try:
            return int(pi_value)
        except ValueError:
            return Decimal(pi_value)
